        links: [ { a: 'SRV1', b: 'R1', bp: gi(1) }, { a: 'R1', ap: gi(0), b: 'NET', bp: gi(0) }, { a: 'NET', ap: gi(1), b: 'R2', bp: gi(0) }, { a: 'R2', ap: gi(1), b: 'PC2' } ],
